alias ClimbOntario.Catalogue.Import
alias ClimbOntario.Repo
venue = fn source_id -> Repo.get_by!(ClimbOntario.Catalogue.Venue, source_gym_id: source_id).id end
base = fn a -> Map.merge(%{published: false, location_kind: "venue", audience: [], cohorts: [], sources: []}, a) end
put! = fn a, s -> case Import.put_listing(base.(a), s) do {:ok, l} -> l; {:error, cs} -> raise "import #{inspect(a.id)} failed: #{inspect(cs.errors)}" end end
patch! = fn a, s -> case Import.put_listing(a, s) do {:ok, l} -> l; {:error, cs} -> raise "patch #{inspect(a.id)} failed: #{inspect(cs.errors)}" end end
